.darma-loader-tw-checkbox-check { position: relative; display: inline-block; width: var(--loader-size, 56px); height: var(--loader-size, 56px); border-radius: calc(var(--loader-size, 56px) * .2); border: calc(var(--loader-size, 56px) * .07) solid var(--loader-color, #22c55e); box-sizing: border-box; animation: darma-loader-tw-checkbox-check-twBoxPop calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-tw-checkbox-check .darma-loader-tw-checkbox-check__tick { position: absolute; left: 26%; top: 16%; width: 32%; height: 54%; border-right: calc(var(--loader-size, 56px) * .09) solid var(--loader-color, #22c55e); border-bottom: calc(var(--loader-size, 56px) * .09) solid var(--loader-color, #22c55e); animation: darma-loader-tw-checkbox-check-twTick calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
@keyframes darma-loader-tw-checkbox-check-twBoxPop { 0%, 100% { transform: scale(1); } 45% { transform: scale(1.1); } }
@keyframes darma-loader-tw-checkbox-check-twTick { 0%, 15% { opacity: 0; transform: rotate(45deg) scale(.2); } 45%, 80% { opacity: 1; transform: rotate(45deg) scale(1); } 100% { opacity: 0; transform: rotate(45deg) scale(.2); } }

